import sys

def find_attr(pattern, modules=None, max_results=10):
    if modules is None:
        modules = [m for m in sys.modules.keys() if not m.startswith('_')]
    results = {}
    for mod in sorted(modules):
        try:
            mod_dict = vars(sys.modules[mod])
            for name, obj in mod_dict.items():
                name_lower = name.lower()
                if pattern in name_lower:
                    results[name_lower] = (mod, name)
        except:
            pass
    return results

